urlset:
{% for p in page.pages %}{% if p.permalink %}{% set full = p | deref %}

  {{ p.permalink }}{% if p.lastmod %}
  {{ p.lastmod | date(format="%Y-%m-%dT%H:%M:%S%:z") }}{% endif %}
  {{ site.params.sitemap.priority | get(key=p.kind, default="") }}
  {% for t in full.translations %}{% endfor %}
{% endif %}{% endfor %}
